import {t,getLanguage} from './i18n.mjs';
import {money,range} from './estimator.mjs';

export function guideAnswer(question,{result,property,location,size}){
  const q=question.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').trim();
  if(/websites?|inonda\.(site|org|homes)|ιστοτοπ|са[йи]т|אתר|site.uri/.test(q))return {text:'All three websites belong to INONDA LTD: inonda.site explains property management, inonda.org covers repairs and renovation services, and inonda.homes helps you plan a budget. Use our website links to continue in your chosen language, then contact the same INONDA team for an inspection and written offer.',action:'network',label:'Explore INONDA websites'};
  if(/contact|whats|viber|phone|call|email|book|quote|appointment|speak|human|irina|constantin|επικοιν|τηλεφ|επιθεωρ|κλεισ|προσφορα|telefon|связ|контакт|звон|огляд|осмотр|oferta|program|зв.яз|התקשר|קשר|טלפון|בדיק|לקבוע|לתאם|תיאום|הצעת/.test(q))return {text:'Talk through your plan with Irina on +357 94 091 616 or Constantin on +357 94 091 613. Both contact lines have WhatsApp, Viber and call buttons. You can also email inonda2026@outlook.com. Our team confirms the scope, site assessment and written quote; this guide cannot make a booking.',action:'contact',label:'Choose your contact'};
  if(/\bvat\b|\btax\b|φπα|\btva\b|ндс|пдв|מע.מ/.test(q))return {text:'All displayed service rates, minimum charges, travel allowances and estimate ranges include 19% VAT. The breakdown shows the included VAT separately. It is not added again at the end.',action:'estimate',label:'See my breakdown'};
  if(/warrant|guarant|εγγυ|гарант|garant|אחריות|registration|he490415|εγγραφ/.test(q))return {text:'INONDA LTD is registered in Cyprus as HE490415 and provides services across Cyprus. The company website states a written workmanship warranty of at least 6 months on labour. Ask the team to confirm the warranty terms in your written offer.',action:'contact',label:'Choose your contact'};
  if(/where|area|location|cyprus|nicosia|limassol|address|based|strovolos|larnaca|paphos|που|κυπρ|λευκωσ|λεμεσ|адрес|кипр|кіпр|unde|adresa|locati|איפה|כתובת|קפריס/.test(q))return {text:'INONDA is based at 29 Charalampou Mouskou, 2014 Strovolos, Nicosia, and offers property services across Cyprus. Select your location in the estimator. Contact the team to confirm availability and travel for your property.',action:'property',label:'Set my location'};
  if(/price|cost|budget|much|pay|current|estimate now|τιμη|κοστο|ποσο|προυπολογ|pret|стоим|бюджет|варт|ціна|кошту|скільки|תקציב|מחיר|עלות|cat costa|buget/.test(q)){
    if(result.errors.length)return {text:'Please check the highlighted property or service inputs first. Once they are valid, I can explain your current planning budget.',action:'property',label:'Check my inputs'};
    if(!result.rows.length)return {text:'Choose one or more services to start your budget. You can mix one-off work with ongoing care and adjust each quantity, rate and minimum charge.',action:'services',label:'Choose services'};
    const totals=[result.rows.some(r=>!r.recurring)?t('{range} one-off (central allowance {central})',{range:range(result.oneOff),central:money(result.oneOff.central)}):null,result.rows.some(r=>r.recurring)?t('{range} per month (central allowance {central})',{range:range(result.monthly),central:money(result.monthly.central)}):null].filter(Boolean).join('; ');
    return {text:t('For your {property} property in {location} ({size} m²), your current plan is {totals}. All figures include 19% VAT. The range reflects your selected scope and assumptions; INONDA must assess the property and agree a written quote.',{property:t(property),location:t(location),size,totals}),action:'estimate',label:'View my estimate'};
  }
  if(/commercial|office|shop|business|residential|villa|apartment|επαγγελμα|κατοικ|γραφει|коммерч|жило|комерц|житло|rezident|birou|מגורים|מסחר/.test(q))return {text:'Choose Residential for an apartment, villa or house, or Commercial for an office, shop or shared facility. The estimator shows the applicable rates and minimums for your selected property type, with 19% VAT included.',action:'property',label:'Choose my property type'};
  if(/clean|καθαρ|уборк|прибиран|curat|ניקיון/.test(q))return {text:'Choose routine, deep or move-in / move-out cleaning. Set the indoor area and choose a one-off visit or ongoing frequency. Routine labour and basic consumables are assumed; specialist machinery, hazardous materials and waste removal need separate agreement.',action:'services',label:'Explore cleaning'};
  if(/alumin|window|shutter|pergola|\bhpl\b|cladding|facade|panel|\bwpc\b|\bpvc\b|αλουμιν|κουφωμ|πανελ|алюмин|алюмін|окн|вікн|панел|אלומיניום|פאנל|ferestr|panou|placar/.test(q))return {text:'Aluminium works, HPL cladding and decorative panels are priced per m², with materials, workmanship and 19% VAT in one rate. Choose the system in each service scope; a site survey and final measurements confirm the quote.',action:'services',label:'Explore aluminium & panels'};
  if(/renovat|kitchen|bathroom|refurb|paint|tiling|ανακαιν|ремонт|renovar|bucatar|שיפו/.test(q))return {text:'Renovation lets you explore a cosmetic refresh, partial refurbishment or full finish refurbishment for a selected area. The allowance covers the selected labour and basic finishes. Structural work, permits, fixtures and major plumbing or electrical works need a separate assessment.',action:'services',label:'Explore renovation'};
  if(/manage|tenant|landlord|διαχειρ|управл|administr|ניהול/.test(q))return {text:'The management allowance covers monthly service coordination and reporting per managed unit. Third-party bills and rent collection are excluded from this estimator. Contact INONDA to discuss the management arrangement you need.',action:'services',label:'Explore management'};
  if(/garden|landscap|outdoor|κηπ|сад|gradin|גינון/.test(q))return {text:'Landscaping covers a routine garden tidy for the outdoor area you enter. You can set one-off or recurring visits. Landscape construction, tall trees, specialist machinery and waste removal need separate agreement.',action:'services',label:'Explore landscaping'};
  if(/maintain|maintenance|handyman|repair|plumb|electri|air condition|συντηρ|επισκευ|обслуж|repar|intretin|תחזוק|תיקון/.test(q))return {text:'Maintenance provides a preventive inspection allowance; handyman provides an hourly labour allowance for small jobs. Parts, repairs and specialist trades are excluded from those allowances. Plumbing and electrical work should be discussed with the team so the right professional can assess it.',action:'services',label:'Explore property care'};
  if(/save|download|print|compare|αποθηκε|ληψη|εκτυπ|скачат|завантаж|зберег|descarc|salv|הורד|שמיר/.test(q))return {text:'Save up to three scenarios in your browser to compare plans. “Download my plan” includes your selected services, quantities, rates, VAT and exclusions. You can also print or save as PDF, then share your plan with INONDA when you contact the team.',action:'estimate',label:'Take my plan with me'};
  if(/month|weekly|recurr|frequency|μηνι|εβδομαδ|συχνοτ|месяц|місяц|lunar|frecvent|חודש|תדיר/.test(q))return {text:'One-off work and ongoing monthly costs are shown separately. Weekly visits average 52 ÷ 12 visits per month. You can change the visit frequency for cleaning, handyman and landscaping; management is monthly.',action:'services',label:'Adjust my visits'};
  return {text:'Start with your property type, location and size. Select the services you need, then adjust the quantities, rates and frequency. Your estimate updates instantly, including 19% VAT. I can help with services, scope, budgets, saved plans and contacting the team. For anything specific to your property, speak with INONDA.',action:'property',label:'Start my estimate'};
}

export function initAssistant({getEstimate}){
  const dialog=document.querySelector('#assistant-dialog'),toggle=document.querySelector('#assistant-toggle'),close=document.querySelector('#assistant-close'),log=document.querySelector('#assistant-log'),input=document.querySelector('#assistant-input');
  function message(text,visitor=false,answer){
    const row=document.createElement('div');row.className=visitor?'assistant-message visitor':'assistant-message';
    const name=document.createElement('small');name.textContent=visitor?'You':'INONDA guide';const body=document.createElement('p');body.textContent=text;if(visitor)body.dataset.noI18n='';row.append(name,body);
    if(answer?.action){const button=document.createElement('button');button.textContent=answer.label;button.addEventListener('click',()=>{const target={contact:'#contact',estimate:'#estimate-card',property:'#property',services:'#services',network:'#inonda-network'}[answer.action];dialog.close();document.querySelector(target)?.scrollIntoView({behavior:'smooth'});});row.append(button);}
    log.append(row);requestAnimationFrame(()=>{log.scrollTop=log.scrollHeight;});
  }
  function ask(question,displayQuestion=question){if(!question.trim())return;const answer=guideAnswer(question.slice(0,300),getEstimate());message(displayQuestion.slice(0,300),true);message(answer.text,false,answer);input.value='';input.focus();}
  toggle.addEventListener('click',()=>{if(dialog.open){dialog.close();return;}dialog.show();toggle.setAttribute('aria-expanded','true');if(!log.children.length)message('Hello. I’m INONDA’s automated guide. Build your own estimate, explore what each service covers, or find the right person to contact. What would you like to plan?');input.focus();});
  close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{toggle.setAttribute('aria-expanded','false');toggle.focus();});
  dialog.addEventListener('keydown',event=>{if(event.key==='Escape')dialog.close();});
  document.querySelector('#assistant-form').addEventListener('submit',event=>{event.preventDefault();ask(input.value);});
  document.addEventListener('inonda:language',()=>{log.replaceChildren();if(dialog.open)message(t('Hello. I’m INONDA’s automated guide. Build your own estimate, explore what each service covers, or find the right person to contact. What would you like to plan?'));});
  document.querySelectorAll('[data-question]').forEach(button=>button.addEventListener('click',()=>ask(button.dataset.question,button.textContent.trim())));
}
